// Default sample images embedded as data URIs.
//
// These are inlined (rather than loaded from f2152.png / f2152_depth.png via a
// relative URL) so the editor also works when index.html is opened directly
// from the file system. Chrome treats every file:// document as an opaque
// origin, so drawing a file:// image onto a canvas taints it and makes
// getImageData()/WebGL texture uploads throw SecurityError.
//
// To change the built-in samples, regenerate the two data URIs below from the
// new PNG files (base64-encoded), or simply drop your own PNGs onto the
// thumbnails in the editor.
window.KANTAI_DEFAULT_IMAGES = {
  baseMap: 'data:image/png;base64,',
  depthMap: 'data:image/png;base64,'
};